{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--earth:#7b5e3f;--warm:#d9c3a5;--accent:#8aa394;--bg:#fbf8f3;--text:#2b2b2b}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--text);background:linear-gradient(180deg,rgba(255,255,255,.6),rgba(250,246,241,.9));}
    header{background:var(--warm);padding:18px 24px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(0,0,0,.05)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--earth),var(--accent));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:14px;color:var(--text);text-decoration:none;font-weight:600}
    .container{max-width:960px;margin:28px auto;padding:16px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:28px;border-radius:12px;background-image:url('assets/img/pattern.svg');background-size:320px;padding-left:34px}
    .hero h1{margin:0;font-size:clamp(22px,4vw,32px);color:var(--earth)}
    .hero p{margin:6px 0 0;color:#3b3b3b}
    .actions{margin-top:14px;display:flex;gap:10px;align-items:center}
    .btn{background:var(--earth);color:#fff;padding:10px 14px;border-radius:8px;border:0;cursor:pointer;font-weight:600}
    .btn.secondary{background:transparent;border:1px solid rgba(0,0,0,.08);color:var(--text)}
    section{margin-top:22px;padding:18px;border-radius:10px;background:rgba(255,255,255,.8);box-shadow:0 6px 18px rgba(27,27,27,.04)}
    h2{margin:0 0 8px;color:var(--earth)}
    .muted{color:#575757;font-size:15px}
    ul{margin:8px 0 0 18px}
    .reveal-on-scroll{opacity:0;transform:translateY(16px);transition:opacity .6s ease,transform .6s ease}
    .reveal-on-scroll.revealed{opacity:1;transform:none}
    footer{margin:36px 0;color:#555;font-size:13px}
    .testimonial{font-style:italic;background:linear-gradient(180deg,rgba(255,255,255,.6),rgba(250,246,241,.6));padding:12px;border-radius:8px}
    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(10,10,10,.45);display:none;align-items:center;justify-content:center;padding:20px}
    .modal{background:#fff;border-radius:12px;max-width:740px;width:100%;padding:20px}
    .exercise-step{display:none}
    .exercise-step.active{display:block}
    .breath-visual{height:80px;width:80px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--earth));margin:12px auto}
    /* prefers-reduced-motion */
    @media (prefers-reduced-motion:reduce){
      .reveal-on-scroll{transition:none}
    }
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">M</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div class="muted" style="font-size:13px">Counseling in {{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Welcome</a>
      <a href="about.html">Who I Am</a>
      <a href="specialties.html">Focus Areas</a>
      <a href="approach.html">How I Work</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero reveal-on-scroll" aria-labelledby="about-hero">
      <div>
        <h1 id="about-hero">A clear, compassionate space to notice and move forward.</h1>
        <p class="muted">I offer focused, time-limited sessions and deeper short programs that help you identify what matters next and practice skills that fit your life.</p>
        <div class="actions">
          <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <button class="btn secondary" id="try-btn">Try it now — guided exercise</button>
        </div>
      </div>
    </section>

    <section class="reveal-on-scroll" aria-labelledby="who-i-am">
      <h2 id="who-i-am">About me, in a few honest sentences</h2>
      <p class="muted">I'm a licensed clinician offering thoughtful, pragmatic care. My work blends evidence-informed strategies with attention to your values and daily realities. I tend to clients who want targeted help for transitions, overwhelm, and relationship patterns.</p>
    </section>

    <section class="reveal-on-scroll" aria-labelledby="social-proof">
      <h2 id="social-proof">What people notice</h2>
      <div class="testimonial">"Helpful at getting to the next practical step, while also making space for what’s hard to name." — A client in {{CITY}}</div>
    </section>

    <section class="reveal-on-scroll" aria-labelledby="benefits">
      <h2 id="benefits">What we can do together</h2>
      <ul>
        <li>Clarify what you most want to change and why it matters.</li>
        <li>Practice small, reliable habits that fit your schedule.</li>
        <li>Plan a focused set of sessions when a particular issue needs attention.</li>
      </ul>
    </section>

    <section class="reveal-on-scroll" aria-labelledby="process">
      <h2 id="process">How an engagement flows</h2>
      <ol>
        <li>Brief intake: we identify priorities and time horizon.</li>
        <li>Focused sessions: practical strategies and supportive reflection.</li>
        <li>Wrap and plan: consolidating next steps and resources to self-manage between meetings.</li>
      </ol>
    </section>

    <section class="reveal-on-scroll" aria-labelledby="faq">
      <h2 id="faq">Quick questions</h2>
      <details>
        <summary>Do you accept insurance?</summary>
        <p class="muted">I am a private-pay clinician. I provide superbills you can submit to some insurers. Payment options are discussed at booking.</p>
      </details>
      <details>
        <summary>Is this suitable for crisis situations?</summary>
        <p class="muted">This practice does not provide emergency crisis services. If you are in danger or need immediate help, call local emergency services or your crisis line.</p>
      </details>
    </section>

    <section class="reveal-on-scroll">
      <h2>Ready to connect?</h2>
      <p class="muted">If you’re curious, click to schedule a first conversation or try a short guided exercise right here.</p>
      <a class="btn" href="{{PRIMARY_CTA_URL}}">Start a conversation</a>
    </section>

    <footer>
      <p>Confidentiality and scope: Sessions are confidential within legal and ethical limits. Therapy is not medical treatment and does not promise outcomes. If you are in immediate danger or experiencing a mental health crisis, call emergency services or your local crisis hotline.</p>
      <p>Contact: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
    </footer>
  </main>

  <div class="modal-backdrop" id="modal" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal" role="document">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <strong id="modal-title">Guided practice</strong>
        <button id="modal-close" aria-label="Close">Close</button>
      </div>
      <p class="muted">Choose a short practice: breath, journaling prompt, or set an intention. These are exercises for present-moment noticing, not therapy in itself.</p>
      <div style="display:flex;gap:8px;margin-top:10px">
        <button class="btn" data-ex="breath">Breathing</button>
        <button class="btn secondary" data-ex="journaling">Journaling</button>
        <button class="btn secondary" data-ex="intention">Intention</button>
      </div>

      <div id="exercise-area" style="margin-top:14px">
        <div class="exercise-step" id="step-breath">
          <div class="breath-visual" id="breath-circle" aria-hidden="true"></div>
          <p class="muted" id="breath-instruction">When you're ready, follow the circle: breathe in for 4, hold 4, out 6. Follow your comfortable rhythm. This is a 2-minute practice.</p>
          <div style="display:flex;gap:8px;margin-top:10px">
            <button class="btn" id="start-breath">Start</button>
            <button class="btn secondary" id="stop-breath">Stop</button>
          </div>
        </div>

        <div class="exercise-step" id="step-journaling">
          <label class="muted">Prompt: "What matters most to me this week?" — write for 5 minutes, freeform.</label>
          <textarea id="journal" rows="6" style="width:100%;margin-top:8px;padding:10px;border-radius:8px;border:1px solid #ddd"></textarea>
          <div style="display:flex;gap:8px;margin-top:8px"><button class="btn" id="save-journal">Done</button></div>
        </div>

        <div class="exercise-step" id="step-intention">
          <p class="muted">A short intention helps practice focus. Choose one:</p>
          <div style="display:flex;gap:8px;margin-top:8px">
            <button class="btn" data-int="gentle">Be gentle with myself</button>
            <button class="btn" data-int="present">Return to the present</button>
            <button class="btn" data-int="action">Take one practical step</button>
          </div>
          <p id="chosen-int" style="margin-top:10px;color:#444"></p>
        </div>
      </div>
    </div>
  </div>

  <script>
    (function(){
      // Scroll reveal with reduced-motion support
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const revealEls = document.querySelectorAll('.reveal-on-scroll');
      function revealNow(){ revealEls.forEach(el=>el.classList.add('revealed')) }
      if(prefersReduced){ revealNow(); }
      else if('IntersectionObserver' in window){
        const io = new IntersectionObserver((entries)=>{
          entries.forEach(e=>{ if(e.isIntersecting) e.target.classList.add('revealed') })
        },{threshold:0.15});
        revealEls.forEach(el=>io.observe(el));
      } else { revealNow(); }

      // Modal practice
      const modal = document.getElementById('modal');
      const tryBtn = document.getElementById('try-btn');
      const closeBtn = document.getElementById('modal-close');
      const exerciseArea = document.getElementById('exercise-area');
      const steps = {breath:document.getElementById('step-breath'),journaling:document.getElementById('step-journaling'),intention:document.getElementById('step-intention')};

      tryBtn.addEventListener('click',()=>{ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); });
      closeBtn.addEventListener('click',()=>{ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); stopBreathing(); });
      modal.addEventListener('click',(e)=>{ if(e.target===modal){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); stopBreathing(); } });

      // choose exercise
      document.querySelectorAll('[data-ex]').forEach(btn=>{
        btn.addEventListener('click',()=>{
          Object.values(steps).forEach(s=>s.classList.remove('active'));
          steps[btn.getAttribute('data-ex')].classList.add('active');
        });
      });

      // Breathing visual
      let breathTimer=null; let breathPhase=0; // 0 in,1 hold,2 out
      const circle = document.getElementById('breath-circle');
      const instr = document.getElementById('breath-instruction');
      function animateBreath(){
        const seq=[{text:'Breathe in — 4',dur:4000,scale:1.3},{text:'Hold — 4',dur:4000,scale:1.3},{text:'Breathe out — 6',dur:6000,scale:0.8}];
        let i=0;
        breathTimer = setInterval(()=>{
          const s = seq[i%seq.length];
          circle.style.transform = 'scale('+s.scale+')';
          instr.textContent = s.text + ' — follow at a comfortable pace.';
          i++;
        },10000);
      }
      function stopBreathing(){ clearInterval(breathTimer); breathTimer=null; circle.style.transform='none'; instr.textContent='When you\'re ready, follow the circle: breathe in for 4, hold 4, out 6. Follow your comfortable rhythm. This is a 2-minute practice.' }
      document.getElementById('start-breath').addEventListener('click',()=>{ if(!breathTimer) animateBreath(); });
      document.getElementById('stop-breath').addEventListener('click',()=>{ stopBreathing(); });

      // Journaling save (local only)
      document.getElementById('save-journal').addEventListener('click',()=>{
        const val = document.getElementById('journal').value.trim();
        if(val) localStorage.setItem('journal-sample',val);
        alert('Saved to browser (local).')
      });

      // Intention choose
      document.querySelectorAll('[data-int]').forEach(btn=>{
        btn.addEventListener('click',()=>{
          document.getElementById('chosen-int').textContent = 'Chosen: "'+btn.getAttribute('data-int')+'" — you might repeat this quietly a few times.';
        });
      });
    })();
  </script>
</body>
</html>"} 
