  <script>
    (function(){
      // Scroll reveal
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const nodes = document.querySelectorAll('.reveal-on-scroll');
      if(reduced) nodes.forEach(n=>n.classList.add('revealed'));
      else if('IntersectionObserver' in window){
        const io = new IntersectionObserver((es)=>{ es.forEach(e=>{ if(e.isIntersecting) e.target.classList.add('revealed') }) },{threshold:.12});
        nodes.forEach(n=>io.observe(n));
      } else nodes.forEach(n=>n.classList.add('revealed'));

      // Modal mini-practice
      const modal = document.getElementById('modal');
      const tryBtn = document.getElementById('try-btn');
      const closeModal = document.getElementById('close-modal');
      const mini = document.getElementById('mini-area');

      tryBtn.addEventListener('click',()=>{ modal.style.display='flex' });
      closeModal.addEventListener('click',()=>{ modal.style.display='none'; mini.innerHTML=''; });

      document.getElementById('breath-start').addEventListener('click',()=>{
        mini.innerHTML = '<div style="text-align:center">\n  <div style="width:84px;height:84px;border-radius:50%;background:linear-gradient(135deg,var(--leaf),var(--twig));margin:10px auto;transform-origin:center;transition:transform .9s ease"></div>\n  <p class="muted">Breathe: in 4, hold 4, out 6. Repeat slowly for one minute.</p>\n</div>';
        // simple animation loop
        const c = mini.querySelector('div');
        let scaleUp = true;
        const t = setInterval(()=>{ c.style.transform = scaleUp? 'scale(1.25)':'scale(.85)'; scaleUp = !scaleUp; },900);
        modal.addEventListener('click',function clear(){ clearInterval(t); modal.removeEventListener('click',clear); },{once:true});
      });

      document.getElementById('intention-start').addEventListener('click',()=>{
        mini.innerHTML = '<div><p class="muted">Pick a short, kind intention. Example: "I will notice one small success today."</p><div style="display:flex;gap:8px;margin-top:8px"><button class="btn">Choose</button></div></div>';
      });
    })();
  </script>
